Set-StrictMode -Version Latest;$ErrorActionPreference='Stop';. (Join-Path $PSScriptRoot 'runner-lib.ps1');if(-not ('PfProcessBridge' -as [type])){Add-Type -Path (Join-Path $PSScriptRoot 'BoundedProcess.cs')}
$scratch=Join-Path ([IO.Path]::GetTempPath()) ('pf native client '+[guid]::NewGuid().ToString('N'));[IO.Directory]::CreateDirectory($scratch)|Out-Null;$source=Join-Path $scratch 'approved input with spaces.sql';Set-Content -LiteralPath $source -Value @('SELECT 1;','SELECT 2;','SELECT 3;');$other=Join-Path $scratch 'unrelated.sql';Set-Content $other 'SELECT 1;';$cancel=Join-Path $scratch 'CANCEL';$spy=[PfSpyProcessAdapter]::new();[PfProcessBridge]::Adapter=$spy;$passed=0
function New-Result([string]$out='',[string]$err='',[int]$exit=0){$r=[PfProcessResult]::new();$r.StdOut=$out;$r.StdErr=$err;$r.ExitCode=$exit;$r.AllStopped=$true;return $r}
function Invoke-Native($result,[string]$expected='^PF_PASS\|native$',[string]$name='case'){$spy.Results.Enqueue($result);return Invoke-PfMvp10Psql 'C:\Program Files\PostgreSQL 17\bin\psql.exe' @('-X','-f',$source) @{} $cancel 1000 $expected (Join-Path $scratch $name)}
try{
 foreach($notice in @('extension "pgcrypto" already exists, skipping','relation "idx_example" already exists, skipping','column "branch_id" of relation "inventory_batches" already exists, skipping','policy "rls_example" for relation "products" does not exist, skipping','trigger "trg_example" for relation "products" does not exist, skipping','constraint "check_example" of relation "stock_ledger" does not exist, skipping')){if((Invoke-Native (New-Result 'PF_PASS|native' "psql:$source`:1: NOTICE: $notice") '^PF_PASS\|native$' ([guid]::NewGuid().ToString('N'))) -cne 'PF_PASS|native'){throw 'benign prefixed notice rejected'}};$passed++
 foreach($diagnostic in @("psql:$other`:1: NOTICE: extension `"pgcrypto`" already exists, skipping","psql:$source`:0: NOTICE: extension `"pgcrypto`" already exists, skipping","psql:$source`:99: NOTICE: extension `"pgcrypto`" already exists, skipping","psql:$source NOTICE: extension `"pgcrypto`" already exists, skipping","psql:$source`:1: CONTEXT: secret=value","psql:$source`:1: NOTICE: password=secret","NOTICE: arbitrary diagnostic")){$failed=$false;$base=[guid]::NewGuid().ToString('N');try{Invoke-Native (New-Result 'PF_PASS|native' $diagnostic) '^PF_PASS\|native$' $base|Out-Null}catch{$failed=$true};if(-not $failed){throw "diagnostic accepted: $diagnostic"};$retained=(Get-Content -Raw (Join-Path $scratch ($base+'.out')))+(Get-Content -Raw (Join-Path $scratch ($base+'.err')));if($retained -match 'unrelated|password|secret|CONTEXT|arbitrary|approved input'){throw 'raw diagnostic path/content retained'}};$passed++
 $workerBase=Join-Path $scratch 'worker';$workerResult=[pscustomobject]@{ExitCode=0;StdOut='PF_EVENT|1|worker-two|READY|backend=802';StdErr="psql:$source`:2: NOTICE: PF_EVENT|1|worker-two|TERMINAL|status=CONFLICT;sqlstate=23505";TimedOut=$false;Cancelled=$false;Overflow=$false;AllStopped=$true};if((Complete-PfMvp10WorkerEvidence $workerResult 'worker-two' 'CONFLICT' $workerBase $source) -ne 802){throw 'prefixed worker terminal rejected'};if((Get-Content -Raw ($workerBase+'.out')) -match 'psql:|approved input'){throw 'raw worker prefix retained'};$passed++
 $failed=$false;$failureBase='nonzero';try{Invoke-Native (New-Result '' "psql:$source`:1: ERROR: password=secret" 1) '^x$' $failureBase|Out-Null}catch{$failed=$true};if(-not $failed -or ((Get-Content -Raw (Join-Path $scratch ($failureBase+'.err'))) -match 'password|secret|approved input')){throw 'nonzero diagnostic retention failed'};$passed++
 $cleanup='PF_RESULT|cleanup|REFUSED|immutable-evidence-preserved';if((Invoke-Native (New-Result $cleanup) '^PF_RESULT\|cleanup\|REFUSED\|immutable-evidence-preserved$' 'cleanup') -cne $cleanup){throw 'cleanup refusal rejected'};$passed++
 $before=$spy.Invocations.Count;Set-Content $cancel 'cancel';$failed=$false;try{Invoke-Native (New-Result 'PF_PASS|native') '^PF_PASS\|native$' 'cancelled'|Out-Null}catch{$failed=$true};if(-not $failed -or $spy.Invocations.Count -ne $before){throw 'cancellation reached native adapter'};$passed++
 Write-Output "PF-MVP-10 native-client prefix/transcript conformance: $passed passed"
}finally{[PfProcessBridge]::Reset();Remove-Item -LiteralPath $scratch -Recurse -Force}
